\begin{defn}[Theorems]
!!^a{formula}~$!A$ is a \emph{theorem} if there is !!a{derivation}
of~$!A$ from the empty set.  We write $\Proves !A$ if $!A$ is a
theorem and $\Proves/ !A$ if it is not.
\end{defn}

\begin{prop}[Compactness]
\ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

\begin{defn}\ollabel{defn:DedekindInfinite}
A set $A$ is \emph{Dedekind infinite} iff there is !!a{injection}
from~$A$ to a proper subset of~$A$. That is, there is some $o \in A$
and !!a{injection} $f \colon A \to A$ such that $o \notin \ran{f}$.
\end{defn}

\begin{prop}
The !!{formula}
  \[
  \fn{Codes}(x, R, Z) \ident \lforall[y][(Z(y) \liff
    R(x, y))]
  \]
expresses that $s(x)$ $s(R)$-codes $s(Z)$.  The
!!{formula} 
\begin{multline*}
  \fn{Pow}(Y, R, X) \ident \\
  \lforall[Z][(Z \subseteq X \lif \lexists[x][(Y(x) \land
    \fn{Codes}(x, R, Z))])] \land {} \\ \lforall[x][(Y(x) \lif
  \lforall[Z][(\fn{Codes}(x, R, Z) \lif Z \subseteq X)]]
\end{multline*}
expresses that $s(Y)$ $s(R)$-codes the power set of~$s(X)$, i.e., the
elements of $s(Y)$ $s(R)$-code exactly the subsets of $s(X)$.
\end{prop}

\begin{thm}
\ollabel{thm:ce-comp}
Let $A$ be any set of natural numbers. Then $A$ is computable if and
only if both $A$ and $\Complement{A}$ are computably enumerable.
\end{thm}

\begin{defn}
  Let $S$ be a set of natural numbers. Then $S$ is \emph{computable}
  iff its characteristic function~$\Char{S}$ is. In other words,
  $S$~is computable iff the function
\[
\Char{S}(x) =
\begin{cases}
1 & \text{if $x \in S$} \\
0 & \text{otherwise}
\end{cases}
\]
is computable. Similarly, a relation $R(x_0, \dots, x_{k-1})$ is
computable if and only if its characteristic function is.

\begin{thm}
\ollabel{thm:ce-equiv}
Let $S$ be a set of natural numbers. Then the following are
equivalent:
\begin{enumerate}
\item\ollabel{case:ce} $S$ is computably enumerable.
\item\ollabel{case:ran-pc} $S$ is the range of a \emph{partial} computable function.
\item\ollabel{case:ran-prim} $S$ is empty or the range of a primitive recursive function.
\item\ollabel{case:ce-domain} $S$ is the \emph{domain} of a partial computable function.
\end{enumerate}
\end{thm}

