A particularly interesting !!{structure} for $\Lang L_Z$ in which the
!!{element}s of the domain are actually sets, and the interpretation
of $\Obj \in$ actually is the relation ``$x$ is !!a{element} of~$y$''
is the !!{structure}~$\Struct{{HF}}$ of \emph{hereditarily finite sets}:
\begin{enumerate}
\item $\Domain{{{HF}}} = \emptyset \cup \Pow{\emptyset} \cup
  \Pow{\Pow{\emptyset}} \cup \Pow{\Pow{\Pow{\emptyset}}} \cup \dots$;
\item $\Assign{\Obj \in}{{{HF}}} = \Setabs{\tuple{x, y}}{x, y \in
  \Domain{{{HF}}}, x \in y}$.
\end{enumerate}
\end{ex}

\begin{defn}\ollabel{def:standard-model}
The \emph{standard model of arithmetic} is the !!{structure}~$\Struct
N$ defined as follows:
\begin{enumerate}
\item $\Domain N = \Nat$
\item $\Assign{\Obj 0}{N} = 0$
\item $\Assign{\Obj \prime}{N}(n) = n + 1$ for all $n \in \Nat$
\item $\Assign{\Obj +}{N}(n, m) = n + m$ for all $n, m \in \Nat$
\item $\Assign{\Obj \times}{N}(n, m) = n\cdot m$ for all $n, m \in \Nat$
\item $\Assign{\Obj <}{N} = \Setabs{\tuple{n, m}}{n \in \Nat, m \in
  \Nat, n < m}$
\end{enumerate}
\end{defn}

(This problem is a special case of what's known as Skolem's Theorem;
$\lforall[x][!A(x,f(x))]$ is called a \emph{Skolem normal form} of
$\lforall[x][\lexists[y][!A(x,y)]]$.)
\end{prob}

We say that~$\Gamma$ is \emph{axiomatized by} a set of
sentences~$\Delta$ if $\Gamma$ is the closure of~$\Delta$.
\end{defn}

\begin{ex}
The theory of strict linear orders in the language~$\Lang L_<$ is
axiomatized by the set
\begin{align*}
\{\quad & \lforall[x][\lnot x < x], \\
& \lforall[x][\lforall[y][((x < y \lor y <
    x) \lor x = y)]], \\
& \lforall[x][\lforall[y][\lforall[z][((x < y
      \land y < z) \lif x < z)]]] \quad \}
\end{align*}
It completely captures the intended !!{structure}s: every strict
linear order is a model of this axiom system, and vice versa, if $R$
is a linear order on a set $X$, then the structure $\Struct M$ with
$\Domain M = X$ and $\Assign{<}{M} = R$ is a model of this theory.
\end{ex}

\begin{ex}
The theory of groups in the language $\Obj 1$ (!!{constant}), $\cdot$
(two-place !!{function}) is axiomatized by
\begin{align*}
& \lforall[x][\eq[(x \cdot \Obj 1)][x]]\\
& \lforall[x][\lforall[y][\lforall[z][\eq[(x \cdot (y \cdot z))][((x
          \cdot y) \cdot z)]]]]\\
& \lforall[x][\lexists[y][\eq[(x \cdot y)][\Obj 1]]]
\end{align*}
\end{ex}

