\end{thm}

\begin{defn}
\ollabel{defn:elem-equiv} 
Given two !!{structure}s $\Struct{M}$ and $\Struct M'$ for the same
!!{language}~$\Lang{L}$, we say that $\Struct{M}$ is \emph{elementarily
  equivalent to} $\Struct M'$, written $\Struct{M} \equiv \Struct M'$,
if and only if for every !!{sentence}~$!A$ of~$\Lang{L}$,
$\Sat{M}{!A}$ iff $\Sat{M'}{!A}$.
\end{defn}

\begin{defn}
Let $\Mod(L){!E}$ denote the class $\Setabs{\Struct{M}}{\Struct{M}
  \models_L !E}$. If the !!{language} needs to be made explicit, we
write $\Mod[L](L){!E}$. Two !!{structure}s $\Struct{M}$ and
$\Struct{N}$ for $\Lang{L}$ are \emph{elementarily equivalent in}
$\tuple{L, \models_L}$, written $\Struct{M} \elemequiv[L] \Struct{N}$, if
the same !!{sentence}s from $L(\Lang{L})$ are true in each.
\end{defn}

\begin{prop}\ollabel{prop:qr-finite}
  Let $\Lang{L}$ be a finite purely relational !!{language}, i.e., a
  !!{language} containing finitely many !!{predicate}s and !!{constant}s,
  and no !!{function}s. Then for each $n \in \Nat$ there are
  only finitely many first-order !!{sentence}s in the !!{language}
  $\Lang{L}$ that have quantifier rank no greater than $n$, up to
  logical equivalence.
\end{prop}

\begin{thm}
\ollabel{thm:ce-equiv}
Let $S$ be a set of natural numbers. Then the following are
equivalent:
\begin{enumerate}
\item\ollabel{case:ce} $S$ is computably enumerable.
\item\ollabel{case:ran-pc} $S$ is the range of a \emph{partial} computable function.
\item\ollabel{case:ran-prim} $S$ is empty or the range of a primitive recursive function.
\item\ollabel{case:ce-domain} $S$ is the \emph{domain} of a partial computable function.
\end{enumerate}
\end{thm}

\begin{proof}
Since every primitive recursive function is computable and every
computable function is partial computable, \olref{case:ran-prim}
implies \olref{case:ce} and \olref{case:ce}
implies~\olref{case:ran-pc}. (Note that if $S$ is empty, $S$~is the
range of the partial computable function that is nowhere defined.) If
we show that \olref{case:ran-pc} implies \olref{case:ran-prim}, we
will have shown the first three clauses equivalent.

\begin{thm}
\ollabel{thm:ce-equiv}
