\begin{defn}[Change of bound variable, $\aconvone$]
  If a term $M$ contains an occurrence of $\lambd[x][N]$, $y \notin
  \FV{N}$, and $\Subst{N}{y}{x}$ is defined, then replacing this occurrence
  by 
  \begin{equation*}
    \lambd[y][\Subst{N}{y}{x}]
  \end{equation*}
  resulting in $M'$ is called a \emph{change of bound variable}, written
  as $M \redone[\alpha] M'$.
\end{defn}

\begin{defn}[parallel $\beta$-reduction, $\bredpar$] \ollabel{defn:bredpar}
  Parallel reduction ($\bredpar$) of terms is inductively defined as follows:
  \begin{enumerate}
    \item \ollabel{defn:bredpar1} $x \bredpar x$.
    \item \ollabel{defn:bredpar2} If $N \xrightarrow{\beta} N'$ then $\lambd[x][N] \bredpar
      \lambd[x][N']$.
    \item \ollabel{defn:bredpar3} If $P \bredpar P'$ and $Q \bredpar Q'$ then $PQ \bredpar
      P'Q'$.
    \item \ollabel{defn:bredpar4} If $N \bredpar N'$ and $Q \bredpar Q'$ then
      $(\lambd[x][N])Q \bredpar \Subst{N'}{Q'}{x}$.
  \end{enumerate}
\end{defn}

\begin{defn}\ollabel{def:goedel} Infinite-valued G\"odel
logic~$\LogGod[\infty]$ is defined using the matrix:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lfalse$, $\lnot$, $\land$, $\lor$, $\lif$.
  \item The set of truth values $V_\infty$.
  \item $1$ is the only designated value, i.e., $V^+ = \{1\}$.
  \item Truth functions are given by the following functions:
  \begin{align*}
    \tf{\lfalse} & = 0\\
    \tf{\lnot}[\LogGod](x) & = \begin{cases}
      $1$ & \text{if } x =0\\
      $0$ & \text{otherwise}
    \end{cases}\\
    \tf{\land}[\LogGod](x,y) & = \min(x,y)\\
    \tf{\lor}[\LogGod](x,y) & = \max(x,y)\\
    \tf{\lif}[\LogGod](x,y) & = \begin{cases}
      1 & \text{if } x \le y\\
      y & \text{otherwise.}
    \end{cases}
    \end{align*}
\end{enumerate}
$m$-valued G\"odel logic is defined the same, except $V = V_m$.
\end{defn}

The number of truth values of a matrix need not be finite.  An obvious
choice for a set of infinitely many truth values is the set of
rational numbers between $0$ and~$1$, $V_\infty = [0,1] \cap \Rat$,
i.e.,
\begin{align*}
    V_\infty & = \Setabs{\frac{n}{m}}{n,m \in \Nat \text{ and } n\le m}.
\intertext{When considering this infinite truth value set, it is often
useful to also consider the subsets}
V_m & = \Setabs{\frac{n}{m-1}}{n \in \Nat \text{ and } n\le m}
\intertext{For instance, $V_5$ is the set with $5$ evenly spaced truth values,}
V_5 & = \{0, \frac{1}{4}, \frac{1}{2}, \frac{3}{4}, 1\}.
\end{align*}
In logics based on these truth value sets, usually only $1$ is
designated, i.e., $V^+ = \{1\}$.  In other words, we let $1$ play the
role of (absolute) truth, $0$ as absolute falsity, but !!{formula}s
may take any intermediate value in~$V$.

\begin{defn}\ollabel{def:lukasiewicz} Infinite-valued \L ukasiewicz
logic~$\LogLuk[\infty]$ is defined using the matrix:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lnot$, $\land$, $\lor$, $\lif$.
  \item The set of truth values $V_\infty$.
  \item $1$ is the only designated value, i.e., $V^+ = \{1\}$.
  \item Truth functions are given by the following functions:
  \begin{align*}
    \tf{\lnot}[\LogLuk](x) & = 1 - x\\
    \tf{\land}[\LogLuk](x,y) & = \min(x,y)\\
    \tf{\lor}[\LogLuk](x,y) & = \max(x,y)\\
    \tf{\lif}[\LogLuk](x,y) & = \min(1,1-(x-y)) = \begin{cases}
      1 & \text{if } x \le y\\
      1-(x-y) & \text{otherwise.}
    \end{cases}
    \end{align*}
\end{enumerate}
$m$-valued \L ukasiewicz logic is defined the same, except $V = V_m$.
\end{defn}

\begin{defn}
The \emph{logic of paradox}~$\LogLP$ is defined using the matrix:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lnot$, $\land$, $\lor$, $\lif$.
  \item The set of truth values $V = \{\True, \Undef, \False\}$.
  \item $\True$ and $\Undef$ are designated, i.e., $V^+ = \{\True, \Undef\}$.
  \item Truth functions are the same as in strong Kleene logic.
\end{enumerate}
\end{defn}

\begin{defn}
Halld\'en's \emph{logic of nonsense}~$\LogHal$ is defined using the matrix:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lnot$, $\land$, $\lor$, $\lif$ and a $1$-place connective~$+$.
  \item The set of truth values $V = \{\True, \Undef, \False\}$.
  \item $\True$ and $\Undef$ are designated, i.e., $V^+ = \{\True, \Undef\}$.
  \item Truth functions are the same as weak Kleene logic, plus the
  ``is meaningless'' operator:
  \begin{center}
    \begin{tabular}{c|c} 
    $\tf{+}$ & \\ 
    \hline  
    $\True$ & $\False$ \\ 
    $\Undef$ & $\True$ \\
    $\False$ & $\False$ 
    \end{tabular}
  \end{center}
\end{enumerate}
\end{defn}

With this definition, it will turn out that the set of !!{derivable}
formulas forms a normal modal logic, and that any !!{derivable}
!!{formula} is true in every model in which every axiom is true. This
property of !!{derivation}s is called \emph{soundness}. The converse,
\emph{completeness}, is harder to prove.

\begin{prop}
  If $!A$ is a substitution instance of $!B$ and $\Log{K} \Proves !B$,
  then $\Log{K} \Proves !A$.
\end{prop}

\begin{proof}
  It is tedious but routine to verify (by induction on the length of
  the !!{derivation} of~$!B$) that applying a substitution to an
  entire !!{derivation} also results in a correct
  !!{derivation}. Specifically, substitution instances of tautological
  instances are themselves tautological instances, substitution
  instances of instances of~\iftag{prvDiamond}{\Dual{} and~}{}\Ax{K}
  are themselves instances of~\iftag{prvDiamond}{\Dual{}
    and~}{}\Ax{K}, and applications of \MP{} and~\Nec{} remain correct
  when substituting !!{formula}s for !!{propositional variable}s in
  both premise(s) and conclusion.
\end{proof}

\begin{prop}
\ollabel{prop:approx-equiv}
The relation $\approx$ has the following properties:
\begin{enumerate}
\item $\approx$ is reflexive.
\item $\approx$ is symmetric.
\item  $\approx$ is transitive.
\item If $t \approx t'$, $f$ is !!a{function}, and $t_1$, \dots,
  $t_{i-1}$, $t_{i+1}$, \dots, $t_n$ are closed terms, then
\[
\Atom{f}{t_1,\dots, t_{i-1}, t, t_{i+1}, \dots, t_n} \approx
\Atom{f}{t_1,\dots, t_{i-1}, t', t_{i+1}, \dots, t_n}.
\]
\item If $t \approx t'$, $R$ is !!a{predicate}, and $t_1$, \dots,
  $t_{i-1}$, $t_{i+1}$, \dots, $t_n$ are closed terms, then
\begin{multline*}
\Atom{R}{t_1,\dots, t_{i-1}, t, t_{i+1}, \dots, t_n} \in \Gamma^* \text{ iff } \\
\Atom{R}{t_1,\dots, t_{i-1}, t', t_{i+1}, \dots, t_n} \in \Gamma^*.
\end{multline*}
\end{enumerate}
\end{prop}

\begin{defn}
  A class~$\mClass{F}$ of frames is \emph{first-order definable} if there is
  !!a{sentence}~$!A$ in the first-order language with a single
  two-place !!{predicate}~$Q$ such that $\mModel{F} =
  \tuple{W, R} \in \mClass{F}$ iff $\Sat{M}{!A}$ in the first-order
  !!{structure}~$\Struct{M}$ with $\Domain{M} = W$ and $\Assign{Q}{M}
  = R$.
\end{defn}

A counterexample to the first is given by the L\"ob formula:
\begin{equation}
\Box(\Box p \lif p) \lif \Box p. \tag{\Ax{W}}
\end{equation}
\Ax{W} defines the class of transitive and converse well-founded
frames. A relation is well-founded if there is no infinite sequence
$w_1$, $w_2$, \dots{} such that $Rw_2w_1$, $Rw_3w_2$, \dots. For
instance, the relation $<$ on~$\Nat$ is well-founded, whereas the
relation $<$ on~$\Int$ is not. A relation is converse well-founded
iff its converse is well-founded. So converse well-founded relations
are those where there is no infinite sequence $w_1$, $w_2$, \dots{}
such that $Rw_1w_2$, $Rw_2w_3$, \dots.

\begin{thm}
  $\alpha$-Conversion is an equivalence relation on terms, i.e., it is
  reflexive, symmetric, and transitive.
\end{thm}

For the inductive step, suppose again that the !!{derivation} of $!B$
from $\Gamma \cup \{!A\}$ ends with a step~$!B$ which is justified by
an inference rule. If the inference rule is modus ponens, we proceed
as in the proof of \olref[ded]{thm:deduction-thm}. If the inference
rule is \QR, we know that $!B \ident !C \lif \lforall[x][!D(x)]$ and
!!a{formula} of the form $!C \lif !D(a)$ appears earlier in the
!!{derivation}, where $a$ does not occur in~$!C$, $!A$, or $\Gamma$. We
thus have that
\begin{align*}
  \Gamma \cup \{!A\} & \Proves !C \lif !D(a),\\
  \intertext{and the induction hypothesis applies, i.e., we have that}
    \Gamma & \Proves !A \lif (!C \lif !D(a)).\\
  \intertext{By}
  & \Proves (!A \lif (!C \lif !D(a))) \lif ((!A \land !C) \lif !D(a))\\
  \intertext{and modus ponens we get}
  \Gamma & \Proves (!A \land !C) \lif !D(a).\\
  \intertext{Since the eigenvariable condition still applies, we can add a step to this !!{derivation} justified by \QR, and get}
    \Gamma & \Proves (!A \land !C) \lif \lforall[x][!D(x)].\\
    \intertext{We also have}
    & \Proves ((!A \land !C) \lif \lforall[x][!D(x)]) \lif (!A \lif (!C \lif \lforall[x][!D(x)]),\\
    \intertext{so by modus ponens,}
    \Gamma & \Proves !A \lif (!C \lif \lforall[x][!D(x)]),
\end{align*}
i.e., $\Gamma \Proves !B$.

We will now establish a number of properties of the !!{derivability}
relation.  They are independently interesting, but each will play a
role in the proof of the completeness theorem.

